template <typename T>
const T &safemax(const T &a, const T &b) {
    if (std::isnan(a)) {
        return b;
    }
    if (std::isnan(b)) {
        return a;
    }
    return (a > b) ? a : b;
}

// Test cases
int main() {
    double a = 1.0, b = 2.0;
    double nan = std::numeric_limits<double>::quiet_NaN();

    // Neither is NaN
    assert(&safemax(a, b) == &b);

    // a is NaN
    assert(&safemax(nan, b) == &b);

    // b is NaN
    assert(&safemax(a, nan) == &a);

    // Both are NaN
    assert(&safemax(nan, nan) == &nan);

    return 0;
}

#include <cmath>
#include <limits>

const double &safemax(const double &a, const double &b) {
    if (std::isnan(a)) {
        return b;
    }
    if (std::isnan(b)) {
        return a;
    }
    return (a > b) ? a : b;
}

// Test cases
int main() {
    double a = 1.0, b = 2.0;
    double nan = std::numeric_limits<double>::quiet_NaN();

    // Neither is NaN
    if (&safemax(a, b) != &b) return 1;

    // a is NaN
    if (&safemax(nan, b) != &b) return 1;

    // b is NaN
    if (&safemax(a, nan) != &a) return 1;

    // Both are NaN
    if (&safemax(nan, nan) != &nan) return 1;

    return 0;
}

